using System.Collections;
using Astrea.BattleActions;
using LittleLeo.Events;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "FabricateSentinelsEffect", menuName = "Data/Battle/Effects/Enemy/FabricateSentinels Effect")]
public class FabricateSentinelsEffect : Effect
{
	[Header("Spawn Minion Action")]
	[SerializeField]
	private CreateAnomalyAction createAnomalyAction;

	[SerializeField]
	private VoidEvent OnSpawnSentinels;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedAtTheEndOfEnemiesTurn()) + AppendedDescription();
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 3)
		{
			return amount;
		}
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueAfterAction(CallBotsCoroutine(effectOwner));
		instance.SetState(instance.ActionsQueueState);
		return amount;
	}

	private IEnumerator CallBotsCoroutine(GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		OnSpawnSentinels.Raise();
		yield return new WaitForSeconds(1f);
		createAnomalyAction.Cast(null);
	}
}
